<?php
require __DIR__ . '/bootstrap.php';
$subject = is_string($_GET['subject'] ?? null) ? trim($_GET['subject']) : '';
$grade = is_string($_GET['grade'] ?? null) ? trim($_GET['grade']) : '';
$where = []; $params = [];
if ($subject !== '') { $where[] = 'subject = ?'; $params[] = $subject; }
if ($grade !== '') { $where[] = 'grade = ?'; $params[] = $grade; }
$sql = 'SELECT id,title,subject,grade,description FROM summaries WHERE published=1';
if ($where) $sql .= ' AND ' . implode(' AND ', $where);
$sql .= ' ORDER BY created_at DESC';
$statement = $pdo->prepare($sql); $statement->execute($params); $rows = $statement->fetchAll();
?><!doctype html><html lang="he" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="icon" href="favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="style.css"><title>סיכומים | מחברת פתוחה</title></head><body class="summaries-page"><header><a class="brand" href="index.php">✦ מחברת פתוחה</a><nav><a href="summaries.php" aria-current="page">סיכומים</a><a href="request.php">בקשת סיכום</a></nav></header><main><h1>סיכומים</h1><?php if ($subject !== '' || $grade !== ''): ?><p class="active-filters" role="status">מציגים סיכומים<?php if ($subject !== ''): ?> במקצוע <?= e($subject) ?><?php endif ?><?php if ($grade !== ''): ?> בכיתה <?= e($grade) ?><?php endif ?>. <a href="summaries.php">לכל הסיכומים</a></p><?php endif ?><div class="cards"><?php foreach ($rows as $s): ?><article class="summary-card"><h2><?= e($s['title']) ?></h2><div class="summary-content<?= trim($s['description']) !== '' ? ' has-description' : '' ?>"><div class="summary-meta"><span>מקצוע:</span><a class="filter-button" href="?subject=<?= rawurlencode($s['subject']) ?>" aria-label="סינון לפי מקצוע <?= e($s['subject']) ?>"><?= e($s['subject']) ?></a><span>כיתה:</span><a class="filter-button" href="?grade=<?= rawurlencode($s['grade']) ?>" aria-label="סינון לפי כיתה <?= e($s['grade']) ?>"><?= e($s['grade']) ?></a></div><?php if (trim($s['description']) !== ''): ?><div class="summary-description"><p><?= e($s['description']) ?></p></div><?php endif ?></div><div class="summary-links"><a class="view-link" href="view.php?id=<?= $s['id'] ?>" target="_blank" rel="noopener">צפייה</a><a class="download-link" href="download.php?id=<?= $s['id'] ?>">הורדה ←</a></div></article><?php endforeach ?><?php if (!$rows): ?><p>לא נמצאו סיכומים מתאימים. <a href="summaries.php">לכל הסיכומים</a></p><?php endif ?></div></main><footer>מחברת פתוחה · נבנה באהבה ללמידה · האתר פונה לכל המגדרים</footer></body></html>
